const dateOf=(date)=>{const d=new Date(date+'T12:00:00');return isNaN(d.getTime())?new Date():d};
const dateShift=(day,n)=>{const d=dateOf(day);d.setDate(d.getDate()+n);return formatISO(d)};
const niceDate=day=>new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(dateOf(day));
