const mediaFor=name=>MEDIA.find(m=>normalize(m.name)===normalize(name)||normalize(m.name).includes(normalize(name))||normalize(name).includes(normalize(m.name)));
const tmSearch=name=>'https://www.transfermarkt.es/schnellsuche/ergebnis/schnellsuche?query='+encodeURIComponent(name||'');
const tmLink=(name,label='Consultar estadísticas en Transfermarkt')=>`<a class="source-cta" href="${esc(tmSearch(name))}" target="_blank" rel="noopener noreferrer">${icon('external','icon-sm')} ${esc(label)}</a>`;
const playerPic=(name,cls='')=>{const m=mediaFor(name);return m?`<img class="player-photo ${cls}" src="${esc(m.url)}" alt="Retrato de ${esc(name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span style="display:none" class="player-photo-fallback ${cls}">${icon('user')}</span>`:`<span class="player-photo-fallback ${cls}">${icon('user')}</span>`};
const creditFor=name=>{const m=mediaFor(name);return m?`<small class="photo-credit">Foto: <a href="${esc(m.source)}" target="_blank" rel="noopener noreferrer">${esc(m.author)}</a> · <a href="${esc(m.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(m.license)}</a></small>`:''};
for(const p of MEDIA){const id='foto-'+DATA.slugify(p.name);PLAYERS.set(id,{id,name:p.name,team:p.team,position:p.position,nation:p.nation,shirt:null,season:null,curated:true});}

const getClub=id=>CLUBS.get(id)||{id,name:id||'Equipo',leagues:[]};
