const state={theme:storage.get('theme','dark'),date:today(),status:'all',region:'all',league:'all',favComps:storage.get('favComps',[]),favTeams:storage.get('favTeams',[]),collapsed:new Set(),tab:'alineaciones',teamTab:'partidos',compTab:'partidos',search:'',searchType:'all',loading:false,loadedDate:null,lastUpdate:null,remoteGames:[],onlineError:false,offlineCount:0,newsFilter:'Todas',transferFilter:'Todos',mode:'online',summaries:{},standings:{},rosters:{},news:[],selectedNews:'all',requestToken:0};
const cache=new Map();
const route=(p,id)=>`#/${p}${id?'/'+encodeURIComponent(id):''}`;
const routeNow=()=>{const p=decodeURIComponent(location.hash.replace(/^#\/?/,'')).split('/').filter(Boolean);return {page:p[0]||'inicio',id:p.slice(1).join('/')||''}};
const star=(what,id)=>`<button class="star-btn ${(what==='comp'?state.favComps.includes(id):state.favTeams.includes(id))?'active':''}" data-action="star-${what}" data-id="${esc(id)}" title="${what==='comp'?'Guardar competición':'Guardar equipo'}" aria-label="Alternar favorito">${icon('star')}</button>`;
const teamIcon=(id,large=false)=>{const t=getClub(id),img=safeUrl(t.logo);return img?`<img class="crest ${large?'crest-lg':''} real-crest" src="${esc(img)}" alt="" loading="lazy" onerror="this.style.display='none'">`:`<span class="crest ${large?'crest-lg':''} real-crest fallback-crest" title="${esc(t.name)}">${esc(t.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span>`};
const leagueMark=c=>`<span class="league-symbol">${esc((c.org||'⚽').slice(0,3).toUpperCase())}</span>`;
