function parseESPN(c,body){let out=[];
  for(const ev of body?.events||[]){const event=ev.competitions?.[0],a=event?.competitors||[],h=a.find(x=>x.homeAway==='home'),v=a.find(x=>x.homeAway==='away');if(!h||!v)continue;
    const mk=t=>{const nm=t.team?.displayName||t.team?.shortDisplayName||t.team?.name||'Equipo';const id=`${c.id}-espn-${t.team?.id||DATA.slugify(nm)}`;
      const ob=CLUBS.get(id)||{id,name:nm,leagues:[c.id],espnId:t.team?.id||null,slug:c.slug};ob.name=nm;ob.leagues=Array.from(new Set([...(ob.leagues||[]),c.id]));ob.espnId=t.team?.id||ob.espnId;ob.slug=c.slug;ob.logo=safeUrl(t.team?.logo)||safeUrl(t.team?.logos?.[0]?.href)||ob.logo||null;CLUBS.set(id,ob);return id};
    const s=ev.status?.type||{},stateName=String(s.state||'').toLowerCase();let status=s.completed||stateName==='post'?'finished':stateName==='in'?'live':'scheduled';if(/postpon|cancel|suspend/i.test(s.name||s.description||''))status='other';
    const date=ev.date||event.date||null;const score=x=>{if(x.score===undefined||x.score===null||x.score==='')return null;const n=Number(x.score);return Number.isFinite(n)?n:null};
    const link=(ev.links||[]).find(l=>l.href&&/espn/i.test(l.href))?.href||null;
    out.push({id:`espn-${c.id}-${ev.id}`,league:c.id,home:mk(h),away:mk(v),homeScore:score(h),awayScore:score(v),date:localDay(date),kickoff:date,status,minute:s.shortDetail||ev.status?.displayClock||'',stage:event?.type?.text||ev.week?.text||'',source:'espn',eventId:ev.id,slug:c.slug,sourceUrl:link,season:c.season,events:[]});
  }return out;
}
async function fetchJSON(url,timeout=9500){const ctr=new AbortController(),tid=setTimeout(()=>ctr.abort(),timeout);try{const res=await fetch(url,{signal:ctr.signal,headers:{Accept:'application/json'},mode:'cors'});if(!res.ok)throw Error('HTTP '+res.status);return await res.json()}finally{clearTimeout(tid)}}
async function pool(items,work,parallel=5){let index=0;async function job(){while(index<items.length){const n=index++;await work(items[n]);}}await Promise.all(Array.from({length:Math.min(parallel,items.length)},job));}
function startRefresh(force=false){const day=state.date;const existing=cache.get(day);if(!force&&existing&&(Date.now()-existing.time)<240000){state.remoteGames=existing.games;state.offlineCount=existing.errors;state.onlineError=existing.errors===comps.length;state.loadedDate=day;state.lastUpdate=existing.time;render();return;}
  if(state.loading){state.queuedDate=day;render();return;}
  const token=++state.requestToken;state.loading=true;state.mode='online';state.onlineError=false;state.offlineCount=0;state.remoteGames=[];state.loadedDate=null;render();
  const games=[],errors=[];const compact=day.replaceAll('-','');
  pool(comps,async c=>{try{const res=await fetchJSON(leagueURL(c)+`?dates=${compact}`,12000);games.push(...parseESPN(c,res));}catch(e){errors.push(c.id)}},5).then(()=>{
    if(token!==state.requestToken)return;
    state.loading=false;state.loadedDate=day;state.remoteGames=games.filter(g=>g.date===day);state.offlineCount=errors.length;state.onlineError=errors.length===comps.length;
    state.lastUpdate=Date.now();cache.set(day,{games:state.remoteGames,errors:errors.length,time:state.lastUpdate});const next=state.queuedDate;state.queuedDate=null;render();if(next&&next!==day)startRefresh();
  });
}
function gamesForDate(){
  const remote=state.loadedDate===state.date?state.remoteGames:[];
  const remoteCompetitions=new Set(remote.map(g=>g.league));
  const backup=[...state.date===archiveDate?archive:[],...officialFixtures.filter(g=>g.date===state.date)];
  return [...remote,...backup.filter(g=>!remoteCompetitions.has(g.league))];
}
function matchesFilter(forceLive=false){return gamesForDate().filter(g=>(!forceLive||g.status==='live')&&(state.status==='all'||g.status===state.status)&&(state.region==='all'||comp(g.league)?.region===state.region)&&(state.league==='all'||g.league===state.league));}
function sortedGroups(rows){const ids=[...new Set(rows.map(g=>g.league))];return ids.sort((a,b)=>Number(state.favComps.includes(b))-Number(state.favComps.includes(a))||['América','Europa','Internacional'].indexOf(comp(a).region)-['América','Europa','Internacional'].indexOf(comp(b).region)||comp(a).name.localeCompare(comp(b).name));}
function statusLabel(g){if(g.source==='archivo')return `<span class="match-time"><b>FIN</b><small>Archivo</small></span>`;
  if(g.status==='live')return `<span class="match-time live"><b>● ${esc(g.minute||'En vivo')}</b><small>En juego</small></span>`;
  if(g.status==='finished')return `<span class="match-time"><b>FIN</b><small>${esc(timeLocal(g.kickoff))}</small></span>`;
  if(g.status==='other')return `<span class="match-time"><b>Revisar</b><small>Estado</small></span>`;
  return `<span class="match-time"><b>${timeLocal(g.kickoff)}</b><small>Por jugar</small></span>`;
}
const scoreDisplay=(g,key)=>g.status==='scheduled'||g[key]==null?'–':String(g[key]);
function matchCard(g){return `<div class="match-row ${g.status==='live'&&g.source==='espn'?'is-live':''}">${statusLabel(g)}<div class="match-teams"><div class="match-team">${teamIcon(g.home)}<span class="team-name">${esc(getClub(g.home).name)}</span></div><div class="match-team">${teamIcon(g.away)}<span class="team-name">${esc(getClub(g.away).name)}</span></div></div><div class="match-score ${g.status==='scheduled'?'score-muted':''}"><span>${scoreDisplay(g,'homeScore')}</span><span>${scoreDisplay(g,'awayScore')}</span></div><div class="match-open">${icon('arrow')}</div><a href="${route('partido',g.id)}" class="match-link-overlay" aria-label="Ver ${esc(getClub(g.home).name)} contra ${esc(getClub(g.away).name)}"></a></div>`}
function matchGroups(list){if(!list.length)return empty('No se encontraron partidos','No hay encuentros disponibles para esta fecha o los filtros seleccionados. Prueba otra fecha o consulta el sitio oficial de la competición.');return sortedGroups(list).map(id=>{
  const c=comp(id),items=list.filter(g=>g.league===id).sort((a,b)=>String(a.kickoff||'').localeCompare(String(b.kickoff||'')));
  return `<section class="surface league-block"><div class="league-head">${leagueMark(c)}<a href="${route('competicion',id)}" class="league-names"><b>${esc(c.name)}</b><small>${esc(c.region)} · ${esc(c.season)}</small></a><span class="league-count">${items.length} partidos</span>${star('comp',id)}<button class="collapse-btn" data-action="collapse" data-id="${id}" aria-label="Contraer o expandir">${icon('down')}</button></div>${state.collapsed.has(id)?'':items.map(matchCard).join('')}</section>`;
}).join('');}
const empty=(title,desc)=>`<div class="surface empty">${icon('info')}<h3>${title}</h3><p>${desc}</p></div>`;
function topHeader(p){const links=[['inicio','Inicio','home'],['en-vivo','En vivo','live'],['calendario','Calendario','calendar'],['competiciones','Ligas','trophy'],['buscar','Buscar','search'],['favoritos','Favoritos','star'],['noticias','Noticias','news'],['fichajes','Fichajes','transfer']];return `<header class="site-header"><div class="header-inner"><a href="#/inicio" class="brand"><img src="assets/img/logo.svg" alt=""><span><span class="brand-name" style="display:block">Cancha Abierta</span><span class="brand-small" style="display:block">Fútbol de verdad, tu cancha</span></span></a><nav class="top-nav" aria-label="Navegación">${links.map(([key,label,ico])=>`<a class="${p===key?'active':''}" href="${route(key)}">${icon(ico)} ${label}</a>`).join('')}</nav><div class="header-actions"><a class="search-quick" href="#/buscar">${icon('search')}<span>Equipos y partidos...</span></a><button class="icon-button" data-action="theme" title="Cambiar tema" aria-label="Cambiar modo claro y oscuro">${icon(state.theme==='dark'?'sun':'moon')}</button><a class="icon-button" href="#/favoritos" title="Favoritos" aria-label="Mis favoritos">${icon('star')}</a></div></div></header><div class="live-disclaimer"><span class="live-bullet"></span> CLUBES Y COMPETICIONES REALES <span class="live-separator">·</span> <span>Resultados ESPN experimental · Archivo histórico 01/11/2026 si no hay conexión · <a href="#/acerca">Ver fuentes</a></span></div>`}
function sideLeft(){const sorted=[...comps].sort((a,b)=>Number(state.favComps.includes(b.id))-Number(state.favComps.includes(a.id))||['Europa','América','Internacional'].indexOf(a.region)-['Europa','América','Internacional'].indexOf(b.region)||a.name.localeCompare(b.name));let old='';return `<aside class="side left"><div class="panel panel-pad"><p class="side-title">${icon('trophy','icon-sm')} Competiciones · 19</p>${sorted.map(c=>{const region=state.favComps.includes(c.id)?'Tus favoritas':c.region,sect=old===region?'':`<div class="side-group">${esc(region)}</div>`;old=region;return `${sect}<a href="${route('competicion',c.id)}" class="side-link"><span class="small-flag">${c.region==='Europa'?'🇪🇺':c.region==='América'?'🌎':'🌍'}</span><span>${esc(c.name)}</span>${state.favComps.includes(c.id)?'<span class="fav-indicator">★</span>':''}</a>`}).join('')}<p class="side-foot">Temporadas 2026/27 y 2026, según torneo. Copa América 2024 y Mundial de Clubes 2025: últimas ediciones.</p></div></aside>`}
function sideRight(){const count=gamesForDate().length;return `<aside class="side right"><div class="panel panel-pad"><p class="side-title">${icon('live','icon-sm')} Panel de jornada</p><div class="metric-grid"><div class="metric"><strong>19</strong><small>Competiciones</small></div><div class="metric"><strong>${count}</strong><small>Partidos mostrados</small></div></div><p class="data-note">${esc(freshness())}</p><button class="tiny-action" data-action="refresh">${icon('refresh','icon-sm')} Consultar ahora</button></div><div class="panel panel-pad"><p class="side-title">${icon('calendar','icon-sm')} Temporadas reales</p>${['premier','laliga','salvador','argentina','mls'].map(id=>{const c=comp(id);return `<a href="${route('competicion',id)}" class="right-feature"><span class="feature-symbol">${icon('trophy')}</span><span><b>${esc(c.name)}</b><small>${esc(c.season)}</small></span></a>`}).join('')}</div><div class="panel panel-pad"><p class="side-title">${icon('news','icon-sm')} Fuentes deportivas</p><a class="right-feature" href="https://www.uefa.com/" target="_blank" rel="noopener noreferrer">${icon('external')} <span><b>UEFA</b><small>Fútbol europeo</small></span></a><a class="right-feature" href="https://www.conmebol.com/" target="_blank" rel="noopener noreferrer">${icon('external')} <span><b>CONMEBOL</b><small>Sudamérica</small></span></a><a class="right-feature" href="https://www.fifa.com/" target="_blank" rel="noopener noreferrer">${icon('external')} <span><b>FIFA</b><small>Competiciones globales</small></span></a></div></aside>`}
function footer(){return `<footer class="footer"><div><b>Cancha Abierta</b> · Fútbol real en una interfaz propia · Prototipo gratuito</div><div>Consulta ESPN no oficial y sujeta a disponibilidad · Archivo histórico: <a target="_blank" rel="noopener noreferrer" href="https://elnine.com.ar/">ELNINE</a> · <a href="#/acerca">Fuentes y límites</a></div></footer>`}
