return `${breadcrumbs([['Competiciones',route('competiciones')],[c.name,route('competicion',c.id)],['Partido',null]])}${head}${tabs([['alineaciones','Alineaciones'],['resumen','Resumen'],['estadisticas','Estadísticas'],['historial','Historial']],t,'match-tab')}${summary==='loading'?'<div class="notice">Cargando información detallada de la fuente...</div>':''}${content}<div class="notice"><b>Fuente:</b> ${g.source==='archivo'?'archivo histórico verificado el 01/11/2026':g.source==='official'?'calendario publicado por UEFA':'consulta experimental del proveedor ESPN'} · Temporada ${esc(c.season)}. La disponibilidad de alineaciones y eventos varía por competición.</div>`;
