async function loadStandings(c){if(state.standings[c.id]!==undefined)return;state.standings[c.id]='loading';render();try{state.standings[c.id]=await fetchJSON(`https://site.api.espn.com/apis/v2/sports/soccer/${encodeURIComponent(c.slug)}/standings`,12000)}catch{state.standings[c.id]='unavailable'}render()}
function standingEntries(value){if(!value||typeof value!=='object')return [];let out=[];const walk=(obj,group)=>{if(Array.isArray(obj))return obj.forEach(x=>walk(x,group));if(!obj||typeof obj!=='object')return;if(obj.standings?.entries)out.push(...obj.standings.entries.map(x=>({...x,group:obj.name||group||''})));if(obj.entries&&Array.isArray(obj.entries))out.push(...obj.entries.map(x=>({...x,group:group||''})));if(obj.children)walk(obj.children,obj.name||group);};walk(value,'');return [...new Map(out.map(x=>[x.team?.id||x.team?.displayName,x])).values()];}
